param([string]$Root="C:\pinchbench-grok-build",[string]$Python="",[string]$SkillDir="",[string]$ProxyUrl="http://127.0.0.1:10090",[string]$AdapterUrl="http://127.0.0.1:8767")
$ErrorActionPreference="Stop";. (Join-Path $PSScriptRoot "common_grok_build_runner.ps1");Set-GrokBenchmarkEnvironment -Root $Root -ProxyUrl $ProxyUrl;Assert-OpenRouterKey;$null=Assert-GrokSearchAdapter -AdapterUrl $AdapterUrl;$p=Resolve-GrokRunnerPaths -Root $Root -Python $Python -SkillDir $SkillDir
$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$out=Join-Path $p.Logs "smoke-$stamp.stdout.txt";$err=Join-Path $p.Logs "smoke-$stamp.stderr.txt";$suite="task_sanity,task_iterative_code_refine,task_stock,task_blog,task_csv_stations_by_elevation"
$args=@("-X","utf8",$p.Runner,"--skill-dir",$p.Skill,"--grok-build-cli",$p.Grok,"--grok-build-home",$p.Home,"--adapter-url",$AdapterUrl,"--suite",$suite,"--judge-model","openrouter/anthropic/claude-opus-5","--timeout-multiplier","3.0","--network-timeout","300","--judge-timeout","300","--results-dir",$p.Runs,"--keep-workspaces","--clear-judge-cache","--verbose")
Write-Host "Starting Grok Build 5-task smoke...";Write-Host "Suite: $suite";$proc=Start-Process -FilePath $p.Python -ArgumentList $args -WorkingDirectory $Root -RedirectStandardOutput $out -RedirectStandardError $err -NoNewWindow -Wait -PassThru;Show-LoggedProcessResult $proc $out $err 260
$latest=Get-ChildItem $p.Runs -Directory -Filter "grok_build_*"|Sort-Object LastWriteTime -Descending|Select-Object -First 1;if($latest){Write-Host "Latest run: $($latest.FullName)"};if($proc.ExitCode-ne 0){throw "Smoke failed with exit code $($proc.ExitCode)"};Write-Host "PASS: Grok Build smoke process completed." -ForegroundColor Green
